  if (req.method === 'GET') return res.status(200).json(todos);
  if (req.method === 'POST') {
    const todo = { id: Date.now(), text: req.body.text };
    todos.push(todo);
    return res.status(201).json(todo);
  }
  res.status(405).end();
}

